mapper.select:
SELECT * FROM (
    SELECT a.id, a.uid, a.code, a.description, a.version, a.mode, a.frequency, a.type, a.triggertype, a.runafter, a.cronexpression, a.reference, a.status
    FROM ${table_prefix_worker}task as a
    WHERE a.deletedDate IS NULL
) a



  LIMIT #{searchRequest.pageRequest.size} OFFSET #{searchRequest.pageRequest.offset}
